package org.brightstats.data;
import java.util.*;import com.google.gson.*;import org.brightstats.stats.*;
public final class RegularizedInput {
 private RegularizedInput(){}
 public static RegularizedSem.Options options(JsonElement value){var o=StatisticalInput.object(value,Set.of("targets","lambdas","mixing","outerFolds","innerFolds","seed","maxIterations","tolerance","selectionTolerance"),"regularized SEM options",false);if(!o.has("targets")||!o.get("targets").isJsonArray()||!o.has("lambdas")||!o.get("lambdas").isJsonArray())throw new IllegalArgumentException("Provide penalty targets and a lambda grid.");List<RegularizedSem.Target> targets=new ArrayList<>();for(var entry:o.getAsJsonArray("targets")){var t=StatisticalInput.object(entry,Set.of("parameter","center","scale"),"penalty target",false);targets.add(new RegularizedSem.Target(StatisticalInput.text(t.get("parameter")),StatisticalInput.number(t,"center",0),StatisticalInput.number(t,"scale",1)));}double[] lambdas=new double[o.getAsJsonArray("lambdas").size()];for(int j=0;j<lambdas.length;j++){JsonObject number=new JsonObject();number.add("value",o.getAsJsonArray("lambdas").get(j));lambdas[j]=StatisticalInput.number(number,"value",0);}return new RegularizedSem.Options(targets,lambdas,StatisticalInput.number(o,"mixing",1),StatisticalInput.integer(o,"outerFolds",3),StatisticalInput.integer(o,"innerFolds",3),StatisticalInput.integer64(o,"seed",42),StatisticalInput.integer(o,"maxIterations",3000),StatisticalInput.number(o,"tolerance",1e-7),StatisticalInput.number(o,"selectionTolerance",1e-6));}
}
